class Score {
  constructor() {
    this.points = 0;
  }

  add() {
    let step = 3;
    this.points += step;
  }

  undo() {
    this.points -= step;
  }
}

const s = new Score();
s.add();
s.undo();

class Counter {
  constructor() {
    this.n = 0;
  }

  addBy(n) {
    n = n + 100;
    this.n += n;
  }
}

let amount = 1;
const c = new Counter();
c.addBy(amount);
console.log(amount);
